 Str2[3];typedef unsigned char Str8[9];// Forward declaration for all the CCharStr_AC classes.class CCharStr_AC;class CChar255_AC;typedef class CCharStr_AC *CCharStrPtr_AC, **CCharStrHandle_AC;// Forward declaration for all the CPascalStr_AC classes.class CPascalStr_AC;class CStr255_AC;typedef class CPascalStr_AC *CPascalStrPtr_AC, **CPascalStrHandle_AC;// Some constants defining the length of each of the CPascalStr_AC types.const unsigned char kStr255Len = 255;const unsigned char kStr63Len = 63;const unsigned char kStr32Len = 32;const unsigned char kStr31Len = 31;const unsigned char kStr27Len = 27;const unsigned char kStr15Len = 15;const unsigned char kStr2Len = 2;const unsigned char kLengthByte = 1;//----------------------------------------------------------------------------------------// CStringTrace_AC//----------------------------------------------------------------------------------------#ifndef qTraceStrings#define qTraceStrings qDebug#endif#if qTraceStringsclass EXPORT_AC CStringTrace_AC// CStringTrace_AC provides support for tracing the usage of strings. It is intended// primarily for tracing the conversion of strings from one format to another. // Obviously it is more efficient to avoid unnecessary copying of strings. // CStringTrace_AC is debug-only, because it relies on debug printing. Because tracing // may generate a huge amount of output, there is a flag to control it. {public:	static bool fgTrace;	static void Trace(const char* inString, const char* inFile, short inLine)	{		if (fgTrace)			Print(inString, inFile, inLine);	}	static void Trace(const unsigned char* inString, const char* inFile, short inLine)	{		if (fgTrace)			Print(inString, inFile, inLine);	}	static void Trace(const std::string& inString, const char* inFile, short inLine)	{		if (fgTrace)			Print(inString, inFile, inLine);	}	static void Trace(const CPascalStr_AC& inString, const char* inFile, short inLine)	{		if (fgTrace)			Print(inString, inFile, inLine);	}	static void Print(const char* inString, const char* inFile, short inLine);	static void Print(const unsigned char* inString, const char* inFile, short inLine);	static void Print(const std::string& inString, const char* inFile, short inLine);	static void Print(const CPascalStr_AC& inString, const char* inFile, short inLine);};#define TraceString_AC(inString) CStringTrace_AC::Trace((inString),  __FILE__, __LINE__)	// The TraceString_AC macro traces the conversion of a string. It is intended to be	// used in a string object constructor where the input string is copied. The file 	// and line number parameters make it clear what the string is being converted to,	// so the string parameter should be the input string. #else#define TraceString_AC(inString)	// The non-debug version of TraceString_AC does nothing. #endif//----------------------------------------------------------------------------------------// CCharStr_AC: simple class to enclose a null terminated c style string.//----------------------------------------------------------------------------------------class EXPORT_AC CCharStr_AC// CCharStr_AC is the base class for all C-style null-terminated// string classes.{public:	//	// No Constructors provided. We don't want anyone constructing this class	// directly since it has no storage. Besides, constructors and assignment operators	// are not inherited anyways.	//	void CopyFrom(const unsigned char* str, unsigned char maxLength);	// From Pascal style string with length byte at beginning	void CopyFrom(const char* str, size_t maxLength);	// From C style string with null terminator at end	void CopyFrom(const void* str, size_t forLength);	// From raw memory for a given length	void CopyFrom(const std::string& str, size_t maxLength);	// From a standard string	size_t Length() const;		bool IsEmpty() const	{ return !*reinterpret_cast<const char*>(this); }	// Character selector operator.	char& operator[](size_t index)	{ return reinterpret_cast<char*>(this)[index]; }	char operator[](size_t index) const	{ return reinterpret_cast<const char*>(this)[index]; }		operator const char*() const	{ return reinterpret_cast<const char*>(this); }	operator char*()	{ return reinterpret_cast<char*>(this); }// •••	operator std::string() const;};//----------------------------------------------------------------------------------------// CChar255_AC://----------------------------------------------------------------------------------------class EXPORT_AC CChar255_AC : public CCharStr_AC{	enum { kMaxLength = kStr255Len };	// The maximum length of the string.public:	CChar255_AC()		{ *reinterpret_cast<char*>(this) = 0; }		CChar255_AC(const char* str)		{ CopyFrom(str, kMaxLength); }		CChar255_AC(const unsigned char* str)		{ CopyFrom(str, kMaxLength); }	CChar255_AC(const void* str, size_t maxLength)		{ CopyFrom(str, maxLength); }	CChar255_AC(const CPascalStr_AC& str)		{ CopyFrom(reinterpret_cast<const unsigned char*>(&str), kMaxLength); }	CChar255_AC(const CStr255_AC& str)		{ CopyFrom(reinterpret_cast<const unsigned char*>(&str), kMaxLength); }	CChar255_AC(const std::string& str)		// Construct a CStr255_AC from a standard string. This should be rarely used,		// because the .c_str method is easier and won't truncate the string. 		{ CopyFrom(str, kMaxLength); TraceString_AC(str); }protected:	char fStr[kMaxLength + 1];			// The character array.};//----------------------------------------------------------------------------------------// TemplateCharStr://----------------------------------------------------------------------------------------template <class T>class TemplateCharStr : public CCharStr_AC{public:	enum { kMaxLength = sizeof(T) - 1 };public:	// Constructors	TemplateCharStr()	{ *reinterpret_cast<char*>(this) = 0; }		TemplateCharStr(const char* str)	{ CopyFrom(str, kMaxLength); }		TemplateCharStr(const unsigned char* str)	{ CopyFrom(str, kMaxLength); }	TemplateCharStr(const void* str, size_t maxLength)	{ CopyFrom(str, maxLength); }	TemplateCharStr(const CPascalStr_AC& str)	{ CopyFrom(reinterpret_cast<const unsigned char*>(&str), kMaxLength); }	TemplateCharStr(const std::string& str)		// Construct a CStr255_AC from a standard string. This should be rarely used,		// because the .c_str method is easier and won't truncate the string. 	{ CopyFrom(str, kMaxLength); TraceString_AC(str); }protected:	T fStr;};//----------------------------------------------------------------------------------------// CPascalStr_AC: Superclass of all Pascal string compatible string classes.//----------------------------------------------------------------------------------------class EXPORT_AC CPascalStr_AC// CPascalStr_AC is the base class for all Pascal string compatible// string classes.{public:	//	// No Constructors provided. We don't want anyone constructing this class	// directly since it has no storage. Besides, constructors and assignment operators	// are not inherited anyways.	//	void CopyFrom(const unsigned char* str, unsigned char maxLength);	// From Pascal style string with length byte at beginning	void CopyFrom(const char* str, unsigned char maxLength);	// From C style string with null terminator at end	void CopyFrom(const void* str, unsigned char forLength);	// From raw memory for a given length	void CopyFrom(const unsigned char* str);	// From Pascal style string with length byte at beginning	// Copies up to kStr255Len bytes, be careful	void CopyFrom(const char* str);	// From C style string with null terminator at end	// Copies up to kStr255Len bytes, be careful#if qPowerPC || qNeedsMC68020	void CopyFrom(unsigned long id)		// From a long value directly into the string	{ *reinterpret_cast<unsigned char*>(this) = sizeof(id); *reinterpret_cast<unsigned long*>(&reinterpret_cast<unsigned char*>(this)[1]) = id; }#else	void CopyFrom(unsigned long id);		// From a long value directly into the string#endif#if qPowerPC || qNeedsMC68020	void CopyFrom(unsigned short num)		// From a short value directly into the string	{ *reinterpret_cast<unsigned char*>(this) = sizeof(num); *reinterpret_cast<unsigned short*>(&reinterpret_cast<unsigned char*>(this)[1]) = num; }#else	void CopyFrom(unsigned short num);		// From a short value directly into the string#endif	void CopyFrom(unsigned char ch)		// From a short value into the string		{ *reinterpret_cast<unsigned char*>(this) = sizeof(ch); reinterpret_cast<unsigned char*>(this)[1] = ch; }	void CopyFrom(const CPascalStr_AC& str, unsigned char maxLength)		// From CPascalStr_AC (Pascal) style string with length byte at beginning		{ CopyFrom(reinterpret_cast<const unsigned char*>(&str), maxLength); }	void CopyFrom(const CPascalStr_AC& str)		// From CPascalStr_AC (Pascal) style string with length byte at beginning		// Copies up to kStr255Len bytes, be careful		{ CopyFrom(reinterpret_cast<const unsigned char*>(&str)); }	void CopyFrom(short strListID, short index, unsigned char maxLength);	// From toolbox Str# resource using GetIndString	void CopyFromSTR(ResNumber STRID, unsigned char maxLength);	// From toolbox STR resource using GetString	void CopyFrom(const Handle inHandle, unsigned char maxLength);	// Copies up to kStr255Len bytes, be careful and use on a string that's big enough	// as indicated in maxLength	void CopyFrom(const std::string& str, unsigned char maxLength);	// From standard string	void CopyTo(unsigned char* str) const;	// Copies this string TO str with a length byte	void CopyTo(char* str) const;	// Copies this string TO str with a null termination	void CopyTo(void* str) const;	// Copies this string TO str without a null termination	unsigned char GetMaxLength(unsigned char pos, unsigned char length) const;	// returns the maximum length to copy starting from pos	// for length characters OR the length of the string whichever comes first.	//	// Character selection operator.	//	unsigned char& operator[](int pos)	{ return reinterpret_cast<unsigned char*>(this)[pos]; }	const unsigned char& operator[](int pos) const	{ return reinterpret_cast<const unsigned char*>(this)[pos]; }		//	// Basic length method, inherited by all derived classes. Returns a reference	//	unsigned char& Length()	{ return *reinterpret_cast<unsigned char*>(this); }	const unsigned char& Length() const	{ return *reinterpret_cast<const unsigned char*>(this); }	bool IsEmpty() const	{ return !*reinterpret_cast<const unsigned char*>(this); }	void Empty()	{ *reinterpret_cast<unsigned char*>(this) = 0; }#if defined(qBackwardCompatible) && qBackwardCompatible	// Returns a copy of the string on the stack. (as a null terminated c style string)	// Note that this will not work when inlining is turned off. MacApp makes no use of this	// operator internally. However, it is still provided as a convenience for compatibility.	// Ideally you should write code that constructs a CChar255_AC in place from your string	operator const char*() const	{ return CChar255_AC(*this); }#endif	// Used to create a toolbox type Str255, etc. from our CPascalStr_AC. This is simply a type	// coercion! Both CPascalStr_AC and Str255, etc. are expected to be pascal-style strings.	operator unsigned char*()	{ return reinterpret_cast<unsigned char*>(this); }		operator const unsigned char*() const	{ return reinterpret_cast<const unsigned char *>(this); }// •••	operator std::string() const;		// Conversion operator that generates a std::string.	//------------------------------------------------------------------------------------		// Return an ID represented as a CPascalStr_AC to the actual ID (an unsigned long).		unsigned long ToULong() const;	unsigned short ToUShort() const;	// Bottleneck CompareText function.	static short CompareText_AC(const void* aPtr, const void* bPtr, short aLen, short bLen);		// Relational operators that are inherited by all the derived CPascalStr_AC types. Five of	// each so that literal C Strings and characters can be conveniently used for one of the	// operators as well as two of the derived classes as operators.	static short CPascalStrCompare(const CPascalStr_AC& s1, const CPascalStr_AC& s2);	static short CPascalStrCompare(const CPascalStr_AC& s1, const char* s2);	static short CPascalStrCompare(const CPascalStr_AC& s1, unsigned char ch);	static short CPascalStrCompare(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStrCompare(s1, *reinterpret_cast<const CPascalStr_AC*>(s2)); }	static short CPascalStrCompare(const char* s1, const CPascalStr_AC& s2);	static short CPascalStrCompare(unsigned char ch, const CPascalStr_AC& s2);	static short CPascalStrCompare(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStrCompare(*reinterpret_cast<const CPascalStr_AC*>(s1), s2); }	friend bool operator==(const CPascalStr_AC& s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) == 0; }	friend bool operator==(const CPascalStr_AC& s1, const char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) == 0; }	friend bool operator==(const CPascalStr_AC& s1, unsigned char ch)					{ return CPascalStr_AC::CPascalStrCompare(s1, ch) == 0; }	friend bool operator==(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) == 0; }	friend bool operator==(const char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) == 0; }	friend bool operator==(unsigned char ch, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(ch, s2) == 0; }	friend bool operator==(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) == 0; }	friend bool operator!=(const CPascalStr_AC& s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) != 0; }	friend bool operator!=(const CPascalStr_AC& s1, const char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) != 0; }	friend bool operator!=(const CPascalStr_AC& s1, unsigned char ch)					{ return CPascalStr_AC::CPascalStrCompare(s1, ch) != 0; }	friend bool operator!=(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) != 0; }	friend bool operator!=(const char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) != 0; }	friend bool operator!=(unsigned char ch, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(ch, s2) != 0; }	friend bool operator!=(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) != 0; }	friend bool operator>(const CPascalStr_AC& s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) > 0; }	friend bool operator>(const CPascalStr_AC& s1, const char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) > 0; }	friend bool operator>(const CPascalStr_AC& s1, unsigned char ch)					{ return CPascalStr_AC::CPascalStrCompare(s1, ch) > 0; }	friend bool operator>(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) > 0; }	friend bool operator>(const char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) > 0; }	friend bool operator>(unsigned char ch, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(ch, s2) > 0; }	friend bool operator>(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) > 0; }	friend bool operator<(const CPascalStr_AC& s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) < 0; }	friend bool operator<(const CPascalStr_AC& s1, const char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) < 0; }	friend bool operator<(const CPascalStr_AC& s1, unsigned char ch)					{ return CPascalStr_AC::CPascalStrCompare(s1, ch) < 0; }	friend bool operator<(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) < 0; }	friend bool operator<(const char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) < 0; }	friend bool operator<(unsigned char ch, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(ch, s2) < 0; }	friend bool operator<(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) < 0; }	friend bool operator>=(const CPascalStr_AC& s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) >= 0; }	friend bool operator>=(const CPascalStr_AC& s1, const char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) >= 0; }	friend bool operator>=(const CPascalStr_AC& s1, unsigned char ch)					{ return CPascalStr_AC::CPascalStrCompare(s1, ch) >= 0; }	friend bool operator>=(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) >= 0; }	friend bool operator>=(const char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) >= 0; }	friend bool operator>=(unsigned char ch, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(ch, s2) >= 0; }	friend bool operator>=(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) >= 0; }	friend bool operator<=(const CPascalStr_AC& s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) <= 0; }	friend bool operator<=(const CPascalStr_AC& s1, const char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) <= 0; }	friend bool operator<=(const CPascalStr_AC& s1, unsigned char ch)					{ return CPascalStr_AC::CPascalStrCompare(s1, ch) <= 0; }	friend bool operator<=(const CPascalStr_AC& s1, const unsigned char* s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) <= 0; }	friend bool operator<=(const char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) <= 0; }	friend bool operator<=(unsigned char ch, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(ch, s2) <= 0; }	friend bool operator<=(const unsigned char* s1, const CPascalStr_AC& s2)					{ return CPascalStr_AC::CPascalStrCompare(s1, s2) <= 0; }	// Concatenation operator that are inherited by all the derived CPascalStr types. Three	// of each so that literal C Strings can be conveniently used for one of the operators	// as well as using any two classes derived from CPascalStr.	friend CStr255_AC operator+(const CPascalStr_AC& s1, const CPascalStr_AC& s2);	friend CStr255_AC operator+(const CPascalStr_AC& s1, const char* s2);	friend CStr255_AC operator+(const CPascalStr_AC& s1, unsigned char ch);	friend CStr255_AC operator+(const CPascalStr_AC& s1, const unsigned char* s2);	friend CStr255_AC operator+(const char* s1, const CPascalStr_AC& s2);	friend CStr255_AC operator+(unsigned char ch, const CPascalStr_AC& s2);	friend CStr255_AC operator+(const unsigned char* s1, const CPascalStr_AC& s2);	// Methods that mimic the Pascal builtin CPascalStr functions for Pos, Insert and Delete.	// Note that insert and copy is implemented in the derived classes.	unsigned char Pos(const char* subStr, unsigned char startPos = 1) const;	unsigned char Pos(const CPascalStr_AC& subStr, unsigned char startPos = 1) const;	unsigned char Pos(char c, unsigned char startPos = 1) const;	void Delete(unsigned char pos, unsigned char length);	void Insert(const char* insStr, unsigned char insStrLength, unsigned char pos, unsigned char maxLength);	void Insert(const char* insStr, unsigned char pos, unsigned char maxLength);	void Insert(const char* insStr, unsigned char pos);	void Insert(const CPascalStr_AC& insStr, unsigned char pos, unsigned char maxLength);	void Insert(const CPascalStr_AC& insStr, unsigned char pos);#if qMSWindows	void AddLineFeeds();	void StripLineFeeds();#endif	//----------------------------------------------------------------------------------------// static member functions//----------------------------------------------------------------------------------------	static Handle SetItl2Handle(Handle itsItl2Handle);//----------------------------------------------------------------------------------------// static data members//----------------------------------------------------------------------------------------	static Handle fgItl2Handle;			// Handle to the international rsrc to be used										// in string compares. Normally NULL, MacApp depends on										// The system value for proper operation of it's internal										// Strings.  However, you may replace and restore the										// value of this field during your own operations.};//----------------------------------------------------------------------------------------// CStr255_AC://----------------------------------------------------------------------------------------class EXPORT_AC CStr255_AC : public CPascalStr_AC// The CStr255_AC class is a subclass of CPascalStr_AC. CStr255_AC// represents a Pascal-style string that is bitwise-compatible with// the string type Str255.{public:	enum { kMaxLength = kStr255Len };public:	CStr255_AC()					{ *reinterpret_cast<unsigned char*>(this) = 0; }		CStr255_AC(const CPascalStr_AC& str)					{ CopyFrom(str); }	// Generic string constructor		CStr255_AC(const CStr255_AC& str)					{ CopyFrom(str); }	// copy constructor	//		// Don't have any optimized constructors for string smaller than me.	// Because all other strings are smaller than me, so we don't need any.	//	CStr255_AC(const unsigned char* str)					{ CopyFrom(str); TraceString_AC(str); }		CStr255_AC(const char* str)					{ CopyFrom(str); TraceString_AC(str); }	CStr255_AC(const char* str, unsigned char maxLength)					{ CopyFrom(str, maxLength); }	CStr255_AC(const void* str, unsigned char forLength)					{ CopyFrom(str, forLength); }	CStr255_AC(unsigned long id)					{ CopyFrom(id); }	CStr255_AC(unsigned short num)					{ CopyFrom(num); }	CStr255_AC(unsigned char ch)					{ CopyFrom(ch); }	CStr255_AC(const std::string& str)					{ CopyFrom(str, kMaxLength); TraceString_AC(str); }	CStr255_AC(short strListID, short index)					{ CopyFrom(strListID, index, kMaxLength); }#if defined(qBackwardCompatible) && qBackwardCompatible	// Returns a copy of the string on the stack. (as a null terminated c style string)	operator const char*() const	{ return CChar255_AC(*this); }#endif	// Copy and Insert roughly equivalent to the Pascal Insert and Copy functions.	CStr255_AC Copy(unsigned char pos, unsigned char length) const					{ return CStr255_AC(reinterpret_cast<const char*>(&(*this)[static_cast<int>(pos)]), GetMaxLength(pos, length)); }	void Insert(const CPascalStr_AC& str, unsigned char pos)					{ CPascalStr_AC::Insert(str, pos); }	void Insert(const char* str, unsigned char pos)					{ CPascalStr_AC::Insert(str, pos); }					   	// Concatenation operator		CStr255_AC& operator +=(const CPascalStr_AC& str)					{ Insert(str, Length() + 1); return *this; }	CStr255_AC& operator +=(const char* str)					{ Insert(str, Length() + 1); return *this; }	CStr255_AC& operator +=(unsigned char ch)					{ CPascalStr_AC::Insert(reinterpret_cast<const char*>(&ch), 1, Length() + 1, kMaxLength); return *this; }	// Assignment operators	CStr255_AC& operator=(const CStr255_AC& str)					{ CopyFrom(str); return *this; }	CStr255_AC& operator=(const CPascalStr_AC& str)					{ CopyFrom(str); return *this; }	CStr255_AC& operator=(const unsigned char* str)					{ CopyFrom(str); return *this; }	CStr255_AC& operator=(const char* str)					{ CopyFrom(str); return *this; }	CStr255_AC& operator=(unsigned char ch)					{ CopyFrom(ch); return *this; }	CStr255_AC& operator=(const std::string& str)					{ CopyFrom(str.c_str()); return *this; }protected:	Str255 fStr;};//----------------------------------------------------------------------------------------// TemplatePascalStr://----------------------------------------------------------------------------------------template <class T>class TemplatePascalStr : public CPascalStr_AC{public:	enum { kMaxLength = sizeof(T) - 1 };public:	// Constructors	TemplatePascalStr()					{ *reinterpret_cast<unsigned char*>(this) = 0; }	TemplatePascalStr(const CPascalStr_AC& str)					{ CopyFrom(str, kMaxLength); }	// Generic string constructor	TemplatePascalStr(const TemplatePascalStr& str)					{ CopyFrom(str); }	// copy constructor		TemplatePascalStr(const unsigned char* str)					{ CopyFrom(str, kMaxLength); TraceString_AC(str); }	TemplatePascalStr(const char* str)					{ CopyFrom(str, kMaxLength); TraceString_AC(str); }	TemplatePascalStr(const char* str, unsigned char maxLength)					{ CopyFrom(str, maxLength); }	TemplatePascalStr(const void* str, unsigned char forLength)					{ CopyFrom(str, forLength); }	TemplatePascalStr(unsigned long id)					{ CopyFrom(id); }	TemplatePascalStr(unsigned short num)					{ CopyFrom(num); }	TemplatePascalStr(unsigned char ch)					{ CopyFrom(ch); }	TemplatePascalStr(const std::string& str)					{ CopyFrom(str, kMaxLength); TraceString_AC(str); }	TemplatePascalStr(short strListID, short index)					{ CopyFrom(strListID, index, kMaxLength); }#if defined(qBackwardCompatible) && qBackwardCompatible	// Returns a copy of the string on the stack. (as a null terminated c style string)	operator const char*() const					{ return CChar255_AC(*this); }#endif	// Copy and Insert roughly equivalent to the Pascal Insert and Copy functions.	void Insert(const CPascalStr_AC& str, unsigned char pos)					{ CPascalStr_AC::Insert(str, pos, kMaxLength); }	void Insert(const char* str, unsigned char pos)					{ CPascalStr_AC::Insert(str, pos, kMaxLength); }	// Concatenation operator	TemplatePascalStr& operator +=(const CPascalStr_AC& str)					{ Insert(str, Length() + 1); return *this; }	TemplatePascalStr& operator +=(const char* str)					{ Insert(str, Length() + 1); return *this; }	TemplatePascalStr& operator +=(unsigned char ch)					{ CPascalStr_AC::Insert(reinterpret_cast<char*>(&ch), 1, Length() + 1, kMaxLength); return *this; }	// Assignment operators	TemplatePascalStr& operator=(const TemplatePascalStr& str)					{ CopyFrom(str); return *this; }	TemplatePascalStr& operator=(const CPascalStr_AC& str)					{ CopyFrom(str, kMaxLength); return *this; }	TemplatePascalStr& operator=(const unsigned char* str)					{ CopyFrom(str, kMaxLength); return *this; }	TemplatePascalStr& operator=(const char* str)					{ CopyFrom(str, kMaxLength); return *this; }	TemplatePascalStr& operator=(unsigned char ch)					{ CopyFrom(ch); return *this; }	TemplatePascalStr& operator=(const std::string& str)					{ CopyFrom(str.c_str(), kMaxLength); return *this; }protected:	T fStr;};// typedef 'em so that existing code still works//typedef TemplateCharStr<Str255> CChar255_AC; // Actually we use a CChar255_AC that has optimizations instead.typedef TemplateCharStr<Str63> CChar63_AC;typedef TemplateCharStr<Str32> CChar32_AC;typedef TemplateCharStr<Str31> CChar31_AC;typedef TemplateCharStr<Str27> CChar27_AC;typedef TemplateCharStr<Str15> CChar15_AC;typedef TemplateCharStr<Str8> CChar8_AC;typedef TemplateCharStr<Str2> CChar2_AC;//typedef TemplatePascalStr<Str255> CStr255_AC; // Actually we use a CStr255_AC that has optimizations instead.typedef TemplatePascalStr<Str63> CStr63_AC;typedef TemplatePascalStr<Str32> CStr32_AC;typedef TemplatePascalStr<Str31> CStr31_AC;typedef TemplatePascalStr<Str27> CStr27_AC;typedef TemplatePascalStr<Str15> CStr15_AC;typedef TemplatePascalStr<Str8> CStr8_AC;typedef TemplatePascalStr<Str2> CStr2_AC;EXPORT_CLASS_AC(